    "agent.dock.free.title": "You are about to allow free driving until the robot is back in the dock:",
    "agent.dock.free.actions": "every move the lock knows: dock.undock · dock.start (also by another modality) · nav.goto_waypoint · nav.goto_xy / nav.goto_offset (a checked point) · nav.execute_path (saved routes) · nav.backup · drive.straight / drive.rotate / drive.velocity (direct driving, always below the gamepad and the web joystick) · mower.program_run / mower.program_resume (saved mowing programs) · motor.on · map.* (mapping)",
    "agent.dock.free.not": "spinning the blade directly — never; mowing only as a saved program",
    "agent.dock.free.uses": "no limit",
    "agent.dock.free.locks": "itself when the robot docks (or after 12 h). Unlocked while it stands in the dock? It waits until the robot leaves and comes back.",
    "agent.dock.free.signed": "you (robert), from this browser",
    "agent.dock.test.button": "Test drive: undock + drive to waypoint + dock back (with recovery)…",
    "agent.dock.test.title": "You are about to allow a test drive:",
    "agent.dock.test.actions": "dock.undock (leave) · nav.goto_waypoint (drive to a saved waypoint) · dock.start (drive back in) · motor.on (power, if needed) · for recovery: nav.backup / drive.straight (back off an obstacle) · drive.rotate (turn) · nav.goto_xy / nav.goto_offset (a detour point) · dock.start_modality (dock by another modality)",
    "agent.dock.test.not": "saved routes (execute_path), mowing programs, the blade, anything else",
    "agent.dock.test.valid": "45 minutes from now",
    "agent.dock.test.uses": "up to 12 moves — one mission with its recoveries, then it is gone",
    "agent.dock.test.signed": "you (robert), from this browser",
    "agent.dock.mow.button": "Mow: run a saved mowing program…",
